from itertools import permutations, combinations

def build_triangle(bottom):
    """Build anti-Pascal triangle from bottom row. Returns list of rows or None if invalid."""
    rows = [list(bottom)]
    current = list(bottom)
    n = len(bottom)
    seen = set()
    for x in current:
        if x == 0 or x in seen:
            return None
        seen.add(x)
    for k in range(1, n):
        next_row = []
        for j in range(len(current) - 1):
            diff = abs(current[j] - current[j + 1])
            if diff == 0 or diff in seen:
                return None
            seen.add(diff)
            next_row.append(diff)
        current = next_row
        rows.append(current)
    return rows

def check_n(n):
    N = n * (n + 1) // 2
    target_count = N
    # N must be in bottom row
    remaining = list(range(1, N))
    count = 0
    for subset in combinations(remaining, n - 1):
        bottom_elements = list(subset) + [N]
        for perm in permutations(bottom_elements):
            count += 1
            rows = build_triangle(perm)
            if rows is not None:
                # Check all entries form {1,...,N}
                all_entries = []
                for row in rows:
                    all_entries.extend(row)
                if len(all_entries) == N and set(all_entries) == set(range(1, N+1)):
                    return True, rows, count
    return False, None, count

