import sys
import time

def backtrack_search(n, time_limit=120, verbose=False):
    """Backtracking search for anti-Pascal triangle with n rows."""
    N = n * (n + 1) // 2
    start = time.time()

    tri = [[0] * n for _ in range(n)]
    used = [False] * (N + 2)
    count = [0]

    def place(pos):
        if pos == n:
            return True
        if time.time() - start > time_limit:
            return False
        count[0] += 1

        for val in range(1, N + 1):
            if used[val]:
                continue

            tri[0][pos] = val
            new_entries = [val]
            conflict = False

            for r in range(1, pos + 1):
                c = pos - r
                diff = abs(tri[r-1][c] - tri[r-1][c+1])
                if diff == 0 or diff > N or used[diff] or diff in new_entries:
                    conflict = True
                    break
                tri[r][c] = diff
                new_entries.append(diff)

            if conflict:
                continue

            for e in new_entries:
                used[e] = True

            if place(pos + 1):
                return True

            for e in new_entries:
                used[e] = False

        return False

    # Try N at each position 0, 1, ..., n-1
    for npos in range(n):
        if time.time() - start > time_limit:
            break
        tri[0][npos] = N
        used[N] = True

        # Fill positions 0..npos-1, then npos+1..n-1
        positions = [p for p in range(n) if p != npos]

        def place_order(idx):
            if idx == len(positions):
                return True
            if time.time() - start > time_limit:
                return False

            pos = positions[idx]
            for val in range(1, N + 1):
                if used[val]:
                    continue
                if time.time() - start > time_limit:
                    return False

                tri[0][pos] = val
                new_entries = [val]
                conflict = False

                for r in range(1, pos + 1):
                    c = pos - r
                    if c < 0 or c + 1 > n - 1 - (r - 1):
                        break
                    # Check if tri[r-1][c] and tri[r-1][c+1] are both set
                    if tri[r-1][c] == 0 or tri[r-1][c+1] == 0:
                        break
                    diff = abs(tri[r-1][c] - tri[r-1][c+1])
                    if diff == 0 or diff > N or used[diff] or diff in new_entries:
                        conflict = True
                        break
                    tri[r][c] = diff
                    new_entries.append(diff)

                if conflict:
                    continue

                for e in new_entries:
                    used[e] = True

                if place_order(idx + 1):
                    return True

                for e in new_entries:
                    used[e] = False
                # Clear tri entries
                for r in range(pos + 1):
                    c = pos - r
                    if 0 <= c < n - r:
                        tri[r][c] = 0

            return False

        if verbose:
            print(f"  Trying N at position {npos}...", flush=True)
        if place_order(0):
            elapsed = time.time() - start
            return True, tri, elapsed, count[0]

        used[N] = False
        tri[0][npos] = 0
        # Clear all tri entries from this attempt
        for r in range(n):
            for c in range(n - r):
                tri[r][c] = 0

    elapsed = time.time() - start
    return False, None, elapsed, count[0]

# Verify n=6 is NO
print("Verifying n=6 (should be NO):", flush=True)
result, tri, elapsed, cnt = backtrack_search(6, time_limit=60, verbose=True)
print(f"n=6: {'YES' if result else 'NO'} (time={elapsed:.1f}s, nodes={cnt})", flush=True)

# Check n=7
print("\nChecking n=7:", flush=True)
result, tri, elapsed, cnt = backtrack_search(7, time_limit=120, verbose=True)
if result:
    print(f"n=7: YES (time={elapsed:.1f}s)")
    for r in range(7):
        print("  ", [tri[r][c] for c in range(7-r)])
else:
    print(f"n=7: NO or timeout (time={elapsed:.1f}s, nodes={cnt})", flush=True)
